(function () {
  // §5.1(2): an unmatched JSONPath resolves to [], and `[] = 'no'` fires a
  // DECLINE nobody intended. Every rule fact is normalised here, once.
  var d = (sub && sub.data) ? sub.data : (sub || {});
  var SENT = cfgSentinel;                 // "__unanswered"
  var NUM_SENT = cfgNumericSentinel;      // -1: below every threshold in the CSV
  var out = {};

  function blank(v) {
    return v === undefined || v === null || v === '' ||
           (Array.isArray(v) && v.length === 0);
  }

  var unansweredInScope = [];
  var selected = Array.isArray(d.selected_products) ? d.selected_products.slice() : [];
  out.selected_products = selected;

  function inScope(prefix) {
    var prods = sectionProducts[prefix];
    if (!prods) return false;
    if (prods.indexOf('*') >= 0) return true;
    for (var i = 0; i < prods.length; i++) {
      if (selected.indexOf(prods[i]) >= 0) return true;
    }
    return false;
  }

  for (var i = 0; i < factCatalogue.length; i++) {
    var fc = factCatalogue[i];
    var raw = d[fc.key];
    var scoped = inScope(fc.section);
    if (blank(raw)) {
      out[fc.key] = (fc.kind === 'number') ? NUM_SENT : SENT;
      if (scoped) unansweredInScope.push(fc.key);
    } else if (fc.kind === 'array') {
      // selected_products is the gate fact and MUST stay an array: `in` cannot
      // read a lowercased string, and a broken gate fires nothing at all, which
      // reads on screen exactly like a correctly-gated ITL-only submission.
      out[fc.key] = Array.isArray(raw) ? raw.slice() : [String(raw)];
    } else if (fc.kind === 'number') {
      var n = Number(String(raw).replace(/[$,\s]/g, ''));
      out[fc.key] = isNaN(n) ? NUM_SENT : n;
      if (isNaN(n) && scoped) unansweredInScope.push(fc.key);
    } else {
      out[fc.key] = String(raw).trim().toLowerCase();
    }
  }

  out.meta_unanswered_in_scope = unansweredInScope;
  out.meta_submission_id = d.submission_id || (sub && sub.id) || '';
  out.meta_quote_id = d.quote_id || '';
  out.meta_submission_version = d.version || d.submitted_version || '';
  out.meta_product_version = d.product_version || '';
  out.meta_distributor_account_id = d.distributor_account_id || '';
  out.meta_broker_id = d.broker_id || '';
  out.meta_policyholder_name = d.gen_policyholder_name || '';

  // Rating inputs. gen_occupation stores the occupation_code, never the label.
  var occ = blank(d.gen_occupation) ? '' : String(d.gen_occupation).trim();
  out.meta_occupation_code = occ;
  // Built here, as one already-resolved string, so the http node never has to
  // pipe-concatenate a digit-leading literal into a query value: a JSON number
  // reaches Go as float64 and "16110170" would go on the wire as 1.611017e+07.
  out.meta_occupation_filter = JSON.stringify([{ field: 'occupation_code', keyword: occ }]);

  var rev = Number(d.gen_total_revenue);
  out.meta_total_revenue = isNaN(rev) ? 0 : rev;

  // product_selections is an untyped array of objects: {product_code, limit_pi,
  // limit_pl, excess}. It is not indexable and has no item schema, so read it
  // defensively and fall back to the occupation's own minimum excess.
  var sels = Array.isArray(d.product_selections) ? d.product_selections : [];
  out.meta_product_selections = sels;
  var itl = null;
  for (var j = 0; j < sels.length; j++) {
    var s = sels[j] || {};
    if (String(s.product_code || s.code || '').toUpperCase() === 'ITL') { itl = s; break; }
  }
  out.meta_itl_selection = itl;
  out.meta_requested_excess = (itl && itl.excess !== undefined && itl.excess !== null && itl.excess !== '')
    ? Number(itl.excess) : null;

  return out;
})();

(function () {
  // ===========================================================================
  // COMBINE_ITPI_PREMIUM — the ONE named, isolated node the plan's
  // [G1f] DECIDED 2026-09-02 block requires (§4.2, condition 2).
  //
  // Antipodean have supplied NO premium formula. They supplied three tables:
  // a rate per hazard class, a discount per revenue band, a factor per excess.
  // The combination below is INFERRED by wave 4 and is not ratified. Replacing
  // it when the real formula lands is an edit to this node and nothing else.
  //
  // Condition 1 of that decision: the rates are READ FROM THE RECORDS
  // (itpi_hazard_rate_config / itpi_size_discount_config /
  // itpi_excess_factor_config). The linear association
  // rate_pi = 0.00473 x (class + 1) is what licensed the inference; it is
  // deliberately NOT evaluated anywhere here, so a corrected table replaces the
  // numbers without touching this flow.
  //
  // Condition 3: every premium produced here is stamped
  // premium_basis = "PROVISIONAL_INFERRED" on decision_config, which is an
  // indexed keyword field, so these quotes can be found again.
  //
  // THE INFERRED ARITHMETIC:
  //   premium_pi = revenue x rate_pi x (1 - discount_percent/100) x excess_factor
  //   premium_pl = revenue x rate_pl x (1 - discount_percent/100) x excess_factor
  //   base       = max(premium_pi + premium_pl, occupation.itpi_min_premium)
  // Money is integer cents throughout (§5.4: there is no decimal type).
  // ===========================================================================
  var errors = [], notes = [];
  function rows(resp) {
    var r = (resp && resp.results) ? resp.results : [];
    var out = [];
    for (var i = 0; i < r.length; i++) out.push(r[i].data || {});
    return out;
  }
  var hazardRows = rows(hz), sizeRows = rows(sz), excessRows = rows(ex);

  // A short page from a reference table is a silent mis-rate, not an error, so
  // assert the row counts the plan's [G1f] load table verified: 21 / 10 / 29.
  if (hazardRows.length !== expect.hazard) errors.push('RATE_TABLE_SHORT:itpi_hazard_rate_config:' + hazardRows.length + '/' + expect.hazard);
  if (sizeRows.length !== expect.size) errors.push('RATE_TABLE_SHORT:itpi_size_discount_config:' + sizeRows.length + '/' + expect.size);
  if (excessRows.length !== expect.excess) errors.push('RATE_TABLE_SHORT:itpi_excess_factor_config:' + excessRows.length + '/' + expect.excess);

  var selected = f.selected_products || [];
  var occRows = (occ && occ.results) ? occ.results : [];
  var occupation = occRows.length ? (occRows[0].data || {}) : null;
  if (!occupation) errors.push('OCCUPATION_NOT_FOUND:' + (f.meta_occupation_code || '(blank)'));

  // Allied Health and General Property have NO rate table in any supplied file
  // (§4.2: gp_hazard_class is empty on all 3347 quotable rows). Wave 4 does not
  // invent one. Any selected product other than ITL is reported unrateable and
  // the engine refers it — see DECIDE.
  var unrateable = [];
  for (var p = 0; p < selected.length; p++) {
    if (rateableProducts.indexOf(selected[p]) < 0) unrateable.push(selected[p]);
  }

  var result = {
    rateable: false,
    premium_basis: 'NOT_RATED',
    base_premium: 0, fsl_levy: 0, gst: 0, stamp_duty: 0, broker_commission: 0,
    total_payable: 0,
    unrateable_products: unrateable,
    errors: errors,
    breakdown: {}
  };

  if (selected.indexOf('ITL') < 0 || !occupation || errors.length) {
    result.breakdown = { reason: errors.length ? 'RATE_INPUTS_UNUSABLE' : 'NO_ITL_SELECTED', notes: notes };
    return result;
  }

  // --- hazard class: occupation_config stores it as a STRING, the rate table
  // as a NUMBER. Coerce, do not compare across types.
  var hazardClass = Number(occupation.itpi_hazard_class);
  var rateRow = null;
  for (var i = 0; i < hazardRows.length; i++) {
    if (Number(hazardRows[i].hazard_class) === hazardClass) { rateRow = hazardRows[i]; break; }
  }
  if (!rateRow) {
    result.errors.push('HAZARD_CLASS_NOT_IN_TABLE:' + occupation.itpi_hazard_class);
    result.breakdown = { reason: 'HAZARD_CLASS_NOT_IN_TABLE' };
    return result;
  }

  // --- size band. Band 1's revenue_min is 0 and the INDEX reads min:0/max:0 as
  // "not supplied", so this table is read whole and bracketed in JS rather than
  // queried: an index filter would silently miss the band most small risks fall in.
  var revenue = Number(f.meta_total_revenue) || 0;
  var sizeRow = null, topRow = null;
  for (var j = 0; j < sizeRows.length; j++) {
    var b = sizeRows[j];
    if (topRow === null || Number(b.revenue_max) > Number(topRow.revenue_max)) topRow = b;
    if (revenue >= Number(b.revenue_min) && revenue <= Number(b.revenue_max)) sizeRow = b;
  }
  if (!sizeRow) {
    // Above the top band ($25m). §4.2 records that bands 9-10 only ever rate a
    // risk already referred at $15m, so this path is reachable only on a referral.
    sizeRow = topRow;
    notes.push('REVENUE_ABOVE_TOP_BAND:used_band:' + (topRow ? topRow.band_id : 'none'));
  }
  var discountPercent = Number(sizeRow.discount_percent) || 0;

  // --- excess factor. $250 is the minimum excess on 329 of the 344 quotable
  // ITPI occupations and is NOT one of the 29 stated points ($100/$200/$300...).
  // §4.2 names this as a defect needing a stated rule. Wave 4's stated rule:
  // take the NEAREST STATED EXCESS AT OR BELOW the requested one (below the
  // lowest point, take the lowest). A lower excess carries a higher factor, so
  // this rounds the premium UP, never down, and it is deterministic. It is
  // recorded on the breakdown so the substitution is visible.
  var requested = (f.meta_requested_excess !== null && f.meta_requested_excess !== undefined && !isNaN(Number(f.meta_requested_excess)))
    ? Number(f.meta_requested_excess)
    : Number(occupation.itpi_min_excess);
  if (isNaN(requested)) requested = Number(occupation.itpi_min_excess) || 0;
  var excessRow = null, lowest = null;
  for (var k = 0; k < excessRows.length; k++) {
    var e = excessRows[k];
    if (lowest === null || Number(e.excess) < Number(lowest.excess)) lowest = e;
    if (Number(e.excess) <= requested && (excessRow === null || Number(e.excess) > Number(excessRow.excess))) excessRow = e;
  }
  if (!excessRow) { excessRow = lowest; notes.push('EXCESS_BELOW_LOWEST_POINT'); }
  if (Number(excessRow.excess) !== requested) {
    notes.push('EXCESS_NOT_IN_TABLE:requested:' + requested + ':used:' + excessRow.excess);
  }
  var excessFactor = Number(excessRow.factor);

  // --- the inferred combination, in integer cents.
  function cents(x) { return Math.round(x * 100); }
  var sizeMult = 1 - (discountPercent / 100);
  var piCents = cents(revenue * Number(rateRow.rate_pi) * sizeMult * excessFactor);
  var plCents = cents(revenue * Number(rateRow.rate_pl) * sizeMult * excessFactor);
  var baseCents = piCents + plCents;
  var minCents = cents(Number(occupation.itpi_min_premium) || 0);
  var minApplied = false;
  if (baseCents < minCents) { baseCents = minCents; minApplied = true; }

  // GST is the statutory 10%; it is not an Antipodean input and is not inferred.
  // FSL/ESL and stamp duty ARE Antipodean inputs (§4.2 items 4 and 5) and NONE
  // has been supplied, so they are zero and named as missing rather than guessed.
  var gstCents = Math.round(baseCents * gstRate);
  var totalCents = baseCents + gstCents;

  result.rateable = true;
  result.premium_basis = 'PROVISIONAL_INFERRED';
  result.base_premium = baseCents / 100;
  result.gst = gstCents / 100;
  result.fsl_levy = 0;
  result.stamp_duty = 0;
  result.broker_commission = 0;
  result.total_payable = totalCents / 100;
  result.breakdown = {
    formula: 'revenue x rate x (1 - discount_percent/100) x excess_factor, per cover section; PROVISIONAL, inferred by wave 4, not supplied by Antipodean',
    revenue: revenue,
    occupation_code: occupation.occupation_code,
    hazard_class: hazardClass,
    rate_pi: Number(rateRow.rate_pi),
    rate_pl: Number(rateRow.rate_pl),
    size_band_id: sizeRow.band_id,
    discount_percent: discountPercent,
    excess_requested: requested,
    excess_used: Number(excessRow.excess),
    excess_factor: excessFactor,
    premium_pi: piCents / 100,
    premium_pl: plCents / 100,
    minimum_premium: minCents / 100,
    minimum_premium_applied: minApplied,
    gst_rate: gstRate,
    not_supplied: ['fsl_esl_rate', 'stamp_duty_schedule', 'broker_commission_basis', 'rounding_and_order_of_operations'],
    unrateable_products: unrateable,
    notes: notes
  };
  return result;
})();

(function () {
  // §5.1 [R]: non-firing rules are ABSENT from the rules node's output, not
  // false. DECIDE therefore keys on PRESENCE and never on 41 keys coming back.
  var fired = [], declines = [], refers = [];
  var brokerReasons = [], uwReasons = [];
  var seenBroker = {};

  for (var name in r) {
    if (!Object.prototype.hasOwnProperty.call(r, name)) continue;
    var outcome = r[name];
    if (outcome === undefined || outcome === null || outcome === '') continue;
    fired.push(name);
    var meta = cat[name] || {};
    if (outcome === 'DECLINE') declines.push(name); else if (outcome === 'REFER') refers.push(name);
    if (meta.uw) uwReasons.push(meta.rule_id + ': ' + meta.uw);
    if (meta.broker && !seenBroker[meta.broker]) { seenBroker[meta.broker] = 1; brokerReasons.push(meta.broker); }
  }

  // Wave 4's answer to artefact 1's open A-11: an unanswered question that is
  // IN SCOPE for a selected product forces REFER. It never forces DECLINE (a
  // missing answer is not an adverse answer) and it never auto-accepts.
  var incomplete = f.meta_unanswered_in_scope || [];
  for (var i = 0; i < incomplete.length; i++) {
    refers.push('INCOMPLETE_SUBMISSION:' + incomplete[i]);
    uwReasons.push('INCOMPLETE_SUBMISSION: ' + incomplete[i] + ' is unanswered and in scope for the selected products.');
  }
  if (incomplete.length && !seenBroker[incompleteBrokerText]) {
    seenBroker[incompleteBrokerText] = 1; brokerReasons.push(incompleteBrokerText);
  }

  // No rate table exists for Allied Health or General Property (§4.2). Wave 4
  // does not invent one and does not fail the run: it REFERS, with a named
  // reason, so the submission still produces a decision record and a task.
  var unrateable = (p && p.unrateable_products) ? p.unrateable_products : [];
  for (var j = 0; j < unrateable.length; j++) {
    refers.push('NO_RATE_TABLE:' + unrateable[j]);
    uwReasons.push('NO_RATE_TABLE: no rate table exists for ' + unrateable[j] + '. Price manually.');
  }
  var rateErrors = (p && p.errors) ? p.errors : [];
  for (var k = 0; k < rateErrors.length; k++) {
    refers.push('RATING_UNAVAILABLE:' + rateErrors[k]);
    uwReasons.push('RATING_UNAVAILABLE: ' + rateErrors[k]);
  }
  if ((unrateable.length || rateErrors.length) && !seenBroker[manualBrokerText]) {
    seenBroker[manualBrokerText] = 1; brokerReasons.push(manualBrokerText);
  }

  // DECLINE beats REFER. Non-negotiable precedence (§5.1, G2).
  var outcome = declines.length ? 'DECLINE' : (refers.length ? 'REFER' : 'ACCEPT');

  var now = new Date();
  var decidedAt = now.toISOString().replace(/\.\d{3}Z$/, 'Z');
  var expiry = new Date(now.getTime() + validityDays * 86400000).toISOString().replace(/\.\d{3}Z$/, 'Z');

  var record = {
    quote_id: f.meta_quote_id,
    submission_id: f.meta_submission_id,
    submission_version: String(f.meta_submission_version || ''),
    product_version: String(f.meta_product_version || ''),
    distributor_account_id: String(f.meta_distributor_account_id || ''),
    product_code: (f.selected_products && f.selected_products.length) ? f.selected_products[0] : '',
    outcome: outcome,
    decision_status: (outcome === 'ACCEPT' || outcome === 'DECLINE') ? 'OPEN' : 'OPEN',
    origin_flow: 'flow-1',
    decided_by: 'engine',
    decided_at: decidedAt,
    decision_seq: Number((seq && (seq.value !== undefined ? seq.value : seq.count)) || 0),
    quote_validity_expiry: expiry,
    sanctions_state: 'not_run',
    referral_reasons: refers,
    decline_reasons: declines,
    broker_reasons: brokerReasons,
    underwriter_reasons: uwReasons,
    premium_basis: (outcome === 'ACCEPT' && p && p.rateable) ? p.premium_basis : 'NOT_RATED',
    base_premium: (outcome === 'ACCEPT' && p && p.rateable) ? p.base_premium : 0,
    gst: (outcome === 'ACCEPT' && p && p.rateable) ? p.gst : 0,
    fsl_levy: 0,
    stamp_duty: 0,
    broker_commission: 0,
    total_payable: (outcome === 'ACCEPT' && p && p.rateable) ? p.total_payable : 0,
    terms: { premium_breakdown: (p && p.breakdown) || {}, rating_provisional: !!(p && p.rateable) }
  };

  return {
    outcome: outcome,
    fired: fired,
    decline_reasons: declines,
    referral_reasons: refers,
    broker_reasons: brokerReasons,
    underwriter_reasons: uwReasons,
    ahc_rules_fired: fired.filter(function (n) { return n.indexOf('DEC_AHC_') === 0; }),
    itcl_rules_fired: fired.filter(function (n) { return n.indexOf('ITCL_') > 0; }),
    decision_record: record
  };
})();
